import {AIPreferencesView} from '../../src/features/ai-preferences.ts';import {Repository} from '../../src/domain/repository.ts';
export function createPreferencesFixture(){const data=new Map<string,string>();let failRead=false,failWrite=false,pending=false,late:(()=>void)|undefined,reads=0,writes=0,id='abcdef123456';const repo=new Repository({read:async k=>{if(failRead)throw Error('读取失败');return data.get(k)??null;},write:async(k,v)=>{if(failWrite)throw Error('写入失败');data.set(k,v);},remove:async k=>{data.delete(k)}});const view=new AIPreferencesView({load:async id=>{reads++;if(pending)await new Promise<void>(r=>late=r);return repo.loadAIPreferences(id);},save:async(id,v)=>{writes++;await repo.saveAIPreferences(id,v);},knowledge:{load:()=>repo.loadAIKnowledgePolicy(),save:async v=>{writes++;await repo.saveAIKnowledgePolicy(v);}}},()=>{});const mount=()=>view.mount(document.querySelector<HTMLElement>('#preferences-host')!,id);mount();return {state:()=>({reads,writes,busy:view.isSaving,dirty:view.hasUnsaved}),reopen:mount,switch:()=>{id=id==='abcdef123456'?'123456abcdef':'abcdef123456';mount();},failRead:(v:boolean)=>failRead=v,failWrite:(v:boolean)=>failWrite=v,pending:()=>pending=true,late:()=>{pending=false;late?.();},leave:()=>view.leave(),value:()=>repo.loadAIPreferences(id),policy:()=>repo.loadAIKnowledgePolicy()};}
